"""Phase 14 bước 4: đo lại ms/khung một lần (ORT CUDA EP, tách riêng từng model, trong gpu_lock)."""
import json
import sys
import time
from datetime import UTC, datetime
from pathlib import Path

import numpy as np

import xla.detect.export_onnx as X
from xla.contract import decode_frame
from xla.eval.enhance_eval import limit_cpu_threads, ort_session
from xla.gpu_lock import gpu_lock
from xla.paths import repo_root

root = repo_root()
threads = limit_cpu_threads()
rows = json.loads((root / "data/real/split.json").read_text(encoding="utf-8"))["frames"]
pick = {s: sorted(r["frame"] for r in rows if r["split"] == s) for s in ("test", "dev")}
dev = pick["dev"]
dev300 = [dev[i] for i in np.linspace(0, len(dev) - 1, 300).round().astype(int)]
sets = {"test100": pick["test"][:100], "dev300": dev300}
frames = {k: [decode_frame(root / "data/real/frames" / f) for f in v] for k, v in sets.items()}
warm = {"test100": 10, "dev300": 30}


def timed(fn, fr, w):
    for f in fr[:w]:
        fn(f)
    t = []
    for f in fr:
        t0 = time.perf_counter()
        fn(f)
        t.append((time.perf_counter() - t0) * 1000)
    v = np.asarray(t)
    return {"p50": round(float(np.median(v)), 3), "p95": round(float(np.percentile(v, 95)), 3),
            "mean": round(float(v.mean()), 3), "n": int(v.size), "warmup": w}


perf_before = X.cpu_performance_pct()
out = {"created": datetime.now(UTC).isoformat(timespec="seconds"), "cpu_threads": threads,
       "cpu_perf_pct_before": perf_before, "models": {}}
with gpu_lock("phase14 ms remeasure", timeout_s=6 * 3600):
    import torch  # noqa: F401 - nạp DLL CUDA cho ORT như export_onnx

    det = X.ort_session(root / "models/release/detector-v1.0.0/detector.onnx", cuda=True)
    enh, active = ort_session(root / "models/release/enhancer-v1.0.0/enhancer.onnx",
                              ["CUDAExecutionProvider", "CPUExecutionProvider"])
    in_name = enh.get_inputs()[0].name
    fns = {"detector": lambda f: X.run_detector(det, f), "enhancer": lambda f: enh.run(None, {in_name: f})}
    for m, fn in fns.items():
        out["models"][m] = {k: timed(fn, frames[k], warm[k]) for k in sets}
    out["providers"] = {"detector": det.get_providers(), "enhancer": active}
out["cpu_perf_pct_after"] = X.cpu_performance_pct(30)
out["note"] = ("mỗi model một session riêng, đo lần lượt (không xen kẽ model khác), khung đã giải mã, gồm chép "
               "host→GPU; detector dùng xla.detect.export_onnx.ort_session/run_detector như meta.ms_per_frame")
out["code"] = Path(__file__).read_text(encoding="utf-8")
Path(sys.argv[1]).write_text(json.dumps(out, ensure_ascii=False, indent=1) + "\n", encoding="utf-8", newline="\n")
print(json.dumps({m: v for m, v in out["models"].items()}, ensure_ascii=False))
print(out["providers"], perf_before and perf_before["mean"], out["cpu_perf_pct_after"] and out["cpu_perf_pct_after"]["mean"])
